<?php
declare(strict_types=1);require_once __DIR__.'/admin_settings.php';$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';if(!preg_match('~^/j/([A-Za-z0-9_-]{6,40})$~',$path,$m)){http_response_code(404);exit('QR invalido');}$token=$m[1];$q=settings_db()->prepare("SELECT vt.label,v.name venueName,v.musicPriceCents,v.dedicationPriceCents,v.mercadoPagoAccessToken FROM venueTables vt JOIN venues v ON v.id=vt.venueId WHERE vt.qrToken=? AND vt.status='ACTIVE' LIMIT 1");$q->execute([$token]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Mesa nao encontrada');}$name=htmlspecialchars((string)$t['venueName'],ENT_QUOTES,'UTF-8');$label=htmlspecialchars((string)$t['label'],ENT_QUOTES,'UTF-8');$music=(int)$t['musicPriceCents'];$ded=(int)$t['dedicationPriceCents'];$ready=!empty($t['mercadoPagoAccessToken']);header('Content-Type:text/html;charset=utf-8');?>
<!doctype html><html lang=pt-BR><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title><?=$name?> · TocaRaul</title><style>*{box-sizing:border-box}body{margin:0;background:#090909;color:#fff;font-family:system-ui}.wrap{max-width:720px;margin:auto;padding:20px 16px 100px}.logo{font-size:28px;font-weight:900;color:#ffcc00}.chip{float:right;background:#171717;border:1px solid #333;border-radius:999px;padding:8px 12px}.hero{margin:28px 0}.hero h1{font-size:36px;margin:0}.grid{display:grid;gap:10px}.song,.card{background:#121212;border:1px solid #292929;border-radius:18px;padding:16px}.song{color:#fff;text-align:left;width:100%;display:flex;justify-content:space-between}.song.selected{border-color:#ffcc00}.song span{color:#999}.song b{color:#ffcc00}.field{margin-top:12px}.field label{display:block;color:#aaa;font-size:13px;margin-bottom:5px}input,textarea{width:100%;background:#070707;color:#fff;border:1px solid #333;border-radius:12px;padding:13px}textarea{min-height:80px}.total{display:flex;justify-content:space-between;font-size:20px;font-weight:900;margin-top:15px}.btn{width:100%;border:0;border-radius:13px;background:#ffcc00;color:#090909;padding:15px;font-weight:900;margin-top:15px}.btn:disabled{opacity:.4}.pix{display:none}.pix.on{display:block}.qr{background:#fff;padding:12px;width:256px;margin:15px auto}.copy{word-break:break-all;background:#070707;padding:10px;border-radius:10px;color:#aaa}.good{color:#aaffb3}.bad{color:#ff9292}</style></head><body><div class=wrap><span class=chip><?=$label?></span><div class=logo>TocaRaul</div><div class=hero><h1>Escolha. Pague. Tocou.</h1><p><?=$name?> · música <b id=base></b></p></div><?php if(!$ready):?><p class=bad>Mercado Pago ainda não conectado pelo bar.</p><?php endif;?><div id=catalog class=grid></div><div class=card style="margin-top:16px"><h2>Seu pedido</h2><div class=field><label>Nome</label><input id=visitor maxlength=80></div><div class=field><label>Dedicatória opcional (+ <span id=ded></span>)</label><textarea id=message maxlength=180></textarea></div><div class=total><span>Total</span><span id=total></span></div><button id=pay class=btn <?=!$ready?'disabled':''?>>Gerar Pix</button><p id=error class=bad></p></div><div id=pix class="card pix"><h2>Pix gerado</h2><div id=pixqr class=qr></div><div id=code class=copy></div><button id=copy class=btn>Copiar Pix</button><p id=status>Aguardando confirmação...</p></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>
const token=<?=json_encode($token)?>,music=<?=$music?>,dedication=<?=$ded?>,ready=<?=$ready?'true':'false'?>;
const songs=[{id:'youtube:dQw4w9WgXcQ',title:'Never Gonna Give You Up',artist:'Rick Astley'},{id:'youtube:kJQP7kiw5Fk',title:'Despacito',artist:'Luis Fonsi ft. Daddy Yankee'},{id:'youtube:9bZkp7q19f0',title:'Gangnam Style',artist:'PSY'},{id:'youtube:fJ9rUzIMcZQ',title:'Bohemian Rhapsody',artist:'Queen'}];let selected=songs[0],requestId=null;const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c/100);base.textContent=money(music);ded.textContent=money(dedication);function refresh(){total.textContent=money(music+(message.value.trim()?dedication:0));catalog.innerHTML='';songs.forEach(s=>{let b=document.createElement('button');b.className='song'+(s.id===selected.id?' selected':'');b.innerHTML='<div><strong>'+s.title+'</strong><br><span>'+s.artist+'</span></div><b>'+money(music)+'</b>';b.onclick=()=>{selected=s;refresh()};catalog.appendChild(b)})}message.oninput=refresh;refresh();
pay.onclick=async()=>{error.textContent='';pay.disabled=true;try{let r=await fetch('/api/commerce/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({qrToken:token,visitorName:visitor.value||'Cliente',providerId:selected.id,title:selected.title,artist:selected.artist,message:message.value,payerEmail:'cliente@tocaraul.app'})});let d=await r.json();if(!r.ok)throw Error(d.message||'Erro ao gerar Pix');requestId=d.requestId;code.textContent=d.pixCopyPaste;pixqr.innerHTML='';new QRCode(pixqr,{text:d.pixCopyPaste,width:232,height:232});pix.classList.add('on');poll()}catch(e){error.textContent=e.message;pay.disabled=!ready}};
async function poll(){try{let r=await fetch('/api/commerce/payment?requestId='+requestId,{cache:'no-store'}),d=await r.json();if(r.ok&&(d.paymentStatus==='APPROVED'||['QUEUED','PLAYING','PLAYED'].includes(d.requestStatus))){status.innerHTML='<b class=good>Pagamento confirmado. Sua música entrou na fila.</b>';return}}catch(e){}setTimeout(poll,2500)}copy.onclick=async()=>{await navigator.clipboard.writeText(code.textContent);copy.textContent='Pix copiado'};
</script></body></html>